    authored.set("The general direction denominator must be √(1+9t⁴), becoming √145 only at t = 2. The final source decimal vector omits division by √145; the correct unit direction is approximately (−0.075513,−0.034559,0.996546). The path lies on x²+y² = 1 with z = t³, and its speed increases as |t| increases.", [{"en": "The general direction denominator must be √(1+9t⁴), becoming √145 only at t = 2. The final source decimal vector omits division by √145; the correct unit direction is approximately (−0.075513,−0.034559,0.996546). The path lies on x²+y² = 1 with z = t³, and its speed increases as |t| increases.", "ur": "عمومی سمت کا مخرج √(1+9t⁴) ہونا چاہیے، جو صرف t = 2 پر √145 بنتا ہے۔ ماخذ کے آخری اعشاری سمتیے میں √145 سے تقسیم غائب ہے؛ درست اکائی سمت تقریباً (−0.075513,−0.034559,0.996546) ہے۔ راستہ x²+y² = 1 پر واقع ہے، جہاں z = t³ ہے، اور |t| بڑھنے پر رفتار بڑھتی ہے۔", "ps": "د عمومي لوري مخرج باید √(1+9t⁴) وي، چې یوازې په t = 2 کې √145 کېږي. د سرچینې وروستی اعشاري ویکتور پر √145 وېش نه لري؛ سم واحد لوری نږدې (−0.075513,−0.034559,0.996546) دی. مسیر پر x²+y² = 1 پروت دی، چې z = t³ دی، او د |t| په زیاتېدو یې چټکتیا زیاتېږي."}]);

    const completedSectionIds = ["sec-5-1", "sec-5-2", "sec-5-3", "sec-5-4"];
    const unit = MATH_12_DATA.find(chapter => Number(chapter.number) === 5);
    const report = { scope: 'Reviewed Unit 5 source-section text, captions, list items and prose table cells only.', completedSectionIds, nextSection: null, sections: [], newPassageEntries: 0 };
    for (const [english, rows] of authored) {
        if (!Object.prototype.hasOwnProperty.call(MATH12_SENTENCE_TRANSLATIONS, english)) {
            MATH12_SENTENCE_TRANSLATIONS[english] = rows;
            report.newPassageEntries++;
        }
    }
    const complete = rows => Array.isArray(rows) && rows.length && rows.every(row => row.en && row.ur && row.ps);
    for (const section of unit?.sections || []) {
        if (!completedSectionIds.includes(section.id)) continue;
        const result = { id: section.id, fields: 0, translatedFields: 0, sentenceRows: 0, missing: [] };
        function attach(original, object, key) {
            if (!original) return;
            result.fields++;
            if (!object[key]?.length && MATH12_SENTENCE_TRANSLATIONS[original]) object[key] = MATH12_SENTENCE_TRANSLATIONS[original];
            if (complete(object[key])) { result.translatedFields++; result.sentenceRows += object[key].length; }
            else result.missing.push(original);
        }
        for (const block of section.sourceBlocks || []) {
            if (['heading', 'paragraph', 'clarification'].includes(block.type)) attach(block.text, block, 'sentenceTranslations');
            if (block.caption) attach(block.caption, block, 'captionSentenceTranslations');
            if (block.alt) attach(block.alt, block, 'altSentenceTranslations');
            if (block.type === 'list') {
                if (!Array.isArray(block.itemSentenceTranslations)) block.itemSentenceTranslations = [];
                (block.items || []).forEach((item, index) => { if (typeof item === 'string') attach(item, block.itemSentenceTranslations, index); });
            }
            if (Array.isArray(block.headers)) {
                if (!Array.isArray(block.headerSentenceTranslations)) block.headerSentenceTranslations = [];
                block.headers.forEach((item, index) => { if (typeof item === 'string' && /[A-Za-z]{2,}/.test(item.replace(/\\\([\s\S]*?\\\)/g, ''))) attach(item, block.headerSentenceTranslations, index); });
            }
            if (Array.isArray(block.rows)) {
                if (!Array.isArray(block.cellSentenceTranslations)) block.cellSentenceTranslations = [];
                block.rows.forEach((row, rowIndex) => {
                    if (!Array.isArray(row)) return;
                    row.forEach((item, index) => {
                        if (typeof item !== 'string' || !/[A-Za-z]{2,}/.test(item.replace(/\\\([\s\S]*?\\\)/g, ''))) return;
                        if (!Array.isArray(block.cellSentenceTranslations[rowIndex])) block.cellSentenceTranslations[rowIndex] = [];
                        attach(item, block.cellSentenceTranslations[rowIndex], index);
                    });
                });
            }
        }
        report.sections.push(result);
    }
    globalThis.MATH12_UNIT5_TRANSLATION_REPORT = report;
